		statusLabel.setVisible(false);

		if (hasText(bountyActionMessage))
		{
			listPanel.add(wrappedCardLine(bountyActionMessage, WARNING_COLOR));
			listPanel.add(verticalGap(6));
		}

		int shown = 0;
		if (bounties != null)
